316	    /// Gaussian elimination with partial pivoting; nil when singular.
317	    private static func solve(_ a: [[Double]], _ b: [Double]) -> [Double]? {
318	        let n = b.count
319	        var m = a
320	        var y = b
321	        for c in 0..<n {
322	            var pivot = c
323	            for r in c + 1..<n where abs(m[r][c]) > abs(m[pivot][c]) { pivot = r }
324	            guard abs(m[pivot][c]) > 1e-15 else { return nil }
325	            m.swapAt(c, pivot)
326	            y.swapAt(c, pivot)
327	            for r in c + 1..<n {
328	                let f = m[r][c] / m[c][c]
329	                guard f != 0 else { continue }
330	                for k in c..<n { m[r][k] -= f * m[c][k] }
331	                y[r] -= f * y[c]
332	            }
333	        }
334	        var x = [Double](repeating: 0, count: n)
335	        for r in stride(from: n - 1, through: 0, by: -1) {
336	            var total = y[r]
337	            for k in r + 1..<n { total -= m[r][k] * x[k] }
338	            x[r] = total / m[r][r]
339	        }
340	        return x
341	    }
342	
343	    /// AU-126 (d): f to 1 Hz, gain to 0.1 dB, Q to 0.01; |gain| < 0.1 dB off.
344	    static func rounded(_ eq: EqProps) -> EqProps {
345	        func gain(_ g: Double) -> Double? {
346	            let r = (g * 10).rounded() / 10
347	            return abs(r) < 0.1 ? nil : r
348	        }
349	        func shelf(_ s: EqShelfProps?) -> EqShelfProps? {
350	            guard let s, let g = gain(s.gainDb) else { return nil }
351	            return EqShelfProps(frequency: s.frequency.rounded(), gainDb: g)
352	        }
353	        func bell(_ s: EqBandProps?) -> EqBandProps? {
354	            guard let s, let g = gain(s.gainDb) else { return nil }
355	            return EqBandProps(
356	                frequency: s.frequency.rounded(), gainDb: g, q: (s.q * 100).rounded() / 100)
357	        }
358	        let bells = [bell(eq.band1), bell(eq.band2), bell(eq.band3)].compactMap { $0 }
359	        return EqProps(
360	            lowShelf: shelf(eq.lowShelf), band1: bells.count > 0 ? bells[0] : nil,
361	            band2: bells.count > 1 ? bells[1] : nil, band3: bells.count > 2 ? bells[2] : nil,
362	            highShelf: shelf(eq.highShelf))
363	    }
364	
365	    // MARK: - The write (AU-127)
366	
367	    /// The target's EQ after the match: its five tonal slots replaced by the
368	    /// fit's, its high- and low-pass kept, `bypass` false.
369	    static func applied(_ fit: Fit, to current: EqProps?) -> EqProps {
370	        var eq = current ?? EqProps()
371	        eq.lowShelf = fit.slots.lowShelf
372	        eq.band1 = fit.slots.band1
373	        eq.band2 = fit.slots.band2
374	        eq.band3 = fit.slots.band3
375	        eq.highShelf = fit.slots.highShelf
376	        eq.bypass = false
377	        return eq
378	    }
379	
380	    /// The EQ a target's spectrum is measured through: its own with the
381	    /// tonal slots off, `bypass` false (the passes kept, so the fit is
382	    /// around them).
383	    static func trialEQ(_ current: EqProps?) -> EqProps {
384	        var eq = current ?? EqProps()
385	        eq.lowShelf = nil
386	        eq.band1 = nil
387	        eq.band2 = nil
388	        eq.band3 = nil
389	        eq.highShelf = nil
390	        eq.bypass = false
391	        return eq
392	    }
393	}
