3	/// Match EQ's arithmetic (road map "audio" AP12, spec §11 AU-125…AU-127):
4	/// two third-octave speech spectra (`SpeechSpectrumMeter`) in, the five
5	/// tonal slots of an `EqProps` out. Pure: no document, no render, no AppKit,
6	/// so `audio_ap12_probe.py` checks it against curves made by the EQ's own
7	/// response.
8	///
9	/// **The curve** (AU-125) is what the target lacks against the reference,
10	/// band by band, with its broadband level taken out — the level is Match
11	/// Loudness's — and smoothed. **The fit** (AU-126) is the EQ whose drawn
12	/// response (`AudioEQDesign.responseDB` of the five tonal slots at 48 kHz at
13	/// the band centres, the curve view's own function) best follows the curve,
14	/// every residual measured up to a constant offset: shelves first, then up
15	/// to three bells placed where the residual is largest, then
16	/// Levenberg–Marquardt over every placed parameter, then rounded.
17	enum AudioMatchFit {
18	    static let maxGainDB = 12.0
19	    static let contentRangeDB = 50.0
20	    static let minimumBands = 12
21	    static let minimumBellDB = 0.5
22	
23	    /// The shelves' starting corners, Hz.
24	    static let lowShelfStart = 150.0
25	    static let highShelfStart = 6000.0
26	    static let maximumBells = 3
27	    /// A new bell sits more than this many bands from an earlier one.
28	    static let bellSpacingBands = 3
29	    static let qRange = 0.5...4.0
30	    static let lowShelfRange = 40.0...500.0
31	    static let highShelfRange = 2000.0...16_000.0
32	    static let bellRange = 60.0...12_000.0
33	    static let maximumIterations = 40
34	    static let sampleRate = 48_000.0
35	
36	    /// The band centres the model is read at.
37	    static let frequencies: [Double] = SpeechSpectrumMeter.bandIndices.map {
38	        SpeechSpectrumMeter.centre($0)
39	    }
40	
41	    /// The fit: only the five tonal slots set, `bypass` false; `rmsDB` the
42	    /// weighted RMS of the offset-free residual over the rounded slots.
43	    struct Fit: Equatable {
44	        let slots: EqProps
45	        let rmsDB: Double
46	    }
47	
48	    // MARK: - The curve (AU-125)
49	
50	    /// How many of `levels` are within `contentRangeDB` of their loudest.
51	    static func contentBands(_ levels: [Double]) -> Int {
52	        guard let top = levels.filter({ $0.isFinite }).max() else { return 0 }
53	        return levels.filter { $0.isFinite && $0 >= top - contentRangeDB }.count
54	    }
55	
56	    /// The curve to fit and its weights: D = reference − target, weight 1
57	    /// where both are within `contentRangeDB` of their own loudest band; the
58	    /// weighted mean of D removed (a band of weight 0 reads 0); smoothed
59	    /// [1, 2, 1]/4 inside and (2, 1)/3 at the ends. nil under `minimumBands`
60	    /// weighted bands, or for spectra of different lengths.
61	    static func target(reference: [Double], target: [Double])
62	        -> (curve: [Double], weights: [Double])?
63	    {
64	        let count = reference.count
65	        guard count == target.count, count >= 2,
66	            let refTop = reference.filter({ $0.isFinite }).max(),
67	            let tgtTop = target.filter({ $0.isFinite }).max()
68	        else { return nil }
69	        var weights = [Double](repeating: 0, count: count)
70	        for b in 0..<count
71	        where reference[b].isFinite && target[b].isFinite
72	            && reference[b] >= refTop - contentRangeDB && target[b] >= tgtTop - contentRangeDB
73	        {
74	            weights[b] = 1
75	        }
76	        guard weights.reduce(0, +) >= Double(minimumBands) else { return nil }
77	        var difference = (0..<count).map { weights[$0] > 0 ? reference[$0] - target[$0] : 0 }
78	        let mean = weightedMean(difference, weights)
79	        difference = (0..<count).map { weights[$0] > 0 ? difference[$0] - mean : 0 }
80	        return (smoothed(difference), weights)
81	    }
82	
83	    /// [1, 2, 1]/4 inside, (2, 1)/3 at each end.
84	    static func smoothed(_ values: [Double]) -> [Double] {
85	        let count = values.count
86	        guard count >= 2 else { return values }
87	        return (0..<count).map { b in
88	            if b == 0 { return (2 * values[0] + values[1]) / 3 }
89	            if b == count - 1 { return (2 * values[b] + values[b - 1]) / 3 }
90	            return (values[b - 1] + 2 * values[b] + values[b + 1]) / 4
91	        }
92	    }
93	
94	    static func weightedMean(_ values: [Double], _ weights: [Double]) -> Double {
95	        var total = 0.0
96	        var weight = 0.0
97	        for b in values.indices where weights[b] > 0 {
98	            total += weights[b] * values[b]
99	            weight += weights[b]
100	        }
101	        return weight > 0 ? total / weight : 0
102	    }
103	
104	    // MARK: - The model
105	
106	    /// The response of `slots` in dB at `frequencies`, 0 where nothing is
107	    /// designed.
108	    static func model(_ slots: EqProps) -> [Double] {
109	        guard let settings = AudioEQSettings(eq: slots, hum: nil) else {
110	            return [Double](repeating: 0, count: frequencies.count)
111	        }
112	        return AudioEQDesign.responseDB(settings, frequencies: frequencies, sampleRate: sampleRate)
113	    }
114	
115	    /// AU-126's residual: curve − model with its weighted mean removed.
116	    static func residual(_ curve: [Double], _ model: [Double], _ weights: [Double]) -> [Double] {
117	        let raw = (0..<curve.count).map { curve[$0] - model[$0] }
118	        let mean = weightedMean(raw, weights)
119	        return raw.map { $0 - mean }
120	    }
121	
122	    static func cost(_ residual: [Double], _ weights: [Double]) -> Double {
123	        var total = 0.0
124	        for b in residual.indices { total += weights[b] * residual[b] * residual[b] }
125	        return total
126	    }
127	
128	    // MARK: - The fit (AU-126)
129	
130	    /// The parameters LM moves: per slot, log f, gain and (bells) log Q.
131	    private struct Params {
132	        var low: (f: Double, g: Double)
133	        var high: (f: Double, g: Double)
134	        var bells: [(f: Double, g: Double, q: Double)]
135	
136	        var vector: [Double] {
137	            var v = [log(low.f), low.g, log(high.f), high.g]
138	            for bell in bells { v += [log(bell.f), bell.g, log(bell.q)] }
139	            return v
140	        }
141	
142	        init(low: (Double, Double), high: (Double, Double), bells: [(Double, Double, Double)]) {
143	            self.low = low
144	            self.high = high
145	            self.bells = bells.map { (f: $0.0, g: $0.1, q: $0.2) }
146	        }
147	
148	        /// From a vector, clamped to AU-126's bounds.
149	        init(_ v: [Double], bells count: Int) {
150	            func clamp(_ x: Double, _ r: ClosedRange<Double>) -> Double {
151	                min(max(x, r.lowerBound), r.upperBound)
152	            }
153	            let gains = -AudioMatchFit.maxGainDB...AudioMatchFit.maxGainDB
154	            low = (clamp(exp(v[0]), lowShelfRange), clamp(v[1], gains))
155	            high = (clamp(exp(v[2]), highShelfRange), clamp(v[3], gains))
156	            bells = (0..<count).map { k in
157	                (f: clamp(exp(v[4 + 3 * k]), bellRange), g: clamp(v[5 + 3 * k], gains),
158	                 q: clamp(exp(v[6 + 3 * k]), qRange))
159	            }
160	        }
161	
162	        var eq: EqProps {
163	            var eq = EqProps()
164	            eq.lowShelf = EqShelfProps(frequency: low.f, gainDb: low.g)
165	            eq.highShelf = EqShelfProps(frequency: high.f, gainDb: high.g)
166	            let sorted = bells.sorted { $0.f < $1.f }
167	            let slots = sorted.map { EqBandProps(frequency: $0.f, gainDb: $0.g, q: $0.q) }
168	            eq.band1 = slots.count > 0 ? slots[0] : nil
169	            eq.band2 = slots.count > 1 ? slots[1] : nil
170	            eq.band3 = slots.count > 2 ? slots[2] : nil
171	            return eq
172	        }
173	    }
