175	    /// The five tonal slots that best follow `curve` under `weights`.
176	    static func fit(curve: [Double], weights: [Double]) -> Fit {
177	        let count = frequencies.count
178	        guard curve.count == count, weights.count == count else {
179	            return Fit(slots: EqProps(), rmsDB: 0)
180	        }
181	        // (a) The shelves' gains, by weighted least squares on their 1 dB
182	        // responses, each offset-free.
183	        let zero = [Double](repeating: 0, count: count)
184	        let unitLow = residual(
185	            model(EqProps(lowShelf: EqShelfProps(frequency: lowShelfStart, gainDb: 1))), zero,
186	            weights)
187	        let unitHigh = residual(
188	            model(EqProps(highShelf: EqShelfProps(frequency: highShelfStart, gainDb: 1))), zero,
189	            weights)
190	        let centred = residual(curve, zero, weights)
191	        var a11 = 0.0, a12 = 0.0, a22 = 0.0, b1 = 0.0, b2 = 0.0
192	        for b in 0..<count {
193	            let w = weights[b]
194	            a11 += w * unitLow[b] * unitLow[b]
195	            a12 += w * unitLow[b] * unitHigh[b]
196	            a22 += w * unitHigh[b] * unitHigh[b]
197	            b1 += w * unitLow[b] * centred[b]
198	            b2 += w * unitHigh[b] * centred[b]
199	        }
200	        let det = a11 * a22 - a12 * a12
201	        var gl = 0.0, gh = 0.0
202	        if abs(det) > 1e-12 {
203	            gl = (b1 * a22 - b2 * a12) / det
204	            gh = (a11 * b2 - a12 * b1) / det
205	        }
206	        var params = Params(
207	            low: (lowShelfStart, min(max(gl, -maxGainDB), maxGainDB)),
208	            high: (highShelfStart, min(max(gh, -maxGainDB), maxGainDB)), bells: [])
209	        // The shelves refined alone, corners too: when they leave no band at
210	        // or above the bell threshold the curve is a tilt, and they are the
211	        // start (no bell will be placed); else the corners stay where they
212	        // started, for the bells to work around.
213	        let shelves = refined(params, curve: curve, weights: weights)
214	        let left = residual(curve, model(shelves.eq), weights)
215	        if left.indices.allSatisfy({ weights[$0] == 0 || abs(left[$0]) < minimumBellDB }) {
216	            params = shelves
217	        }
218	
219	        // (b) Up to three bells, greedily, where the residual is largest.
220	        var placed: [Int] = []
221	        for _ in 0..<maximumBells {
222	            let r = residual(curve, model(params.eq), weights)
223	            var best: Int?
224	            for b in 0..<count where weights[b] > 0 && abs(r[b]) >= minimumBellDB {
225	                guard placed.allSatisfy({ abs($0 - b) > bellSpacingBands }) else { continue }
226	                if best == nil || abs(r[b]) > abs(r[best!]) { best = b }
227	            }
228	            guard let b = best else { break }
229	            placed.append(b)
230	            var run = 1
231	            for direction in [-1, 1] {
232	                var k = b + direction
233	                while k >= 0, k < count, weights[k] > 0, r[k].sign == r[b].sign,
234	                    abs(r[k]) >= abs(r[b]) / 2
235	                {
236	                    run += 1
237	                    k += direction
238	                }
239	            }
240	            let octaves = Double(run) / 3
241	            let q = min(max(pow(2, octaves / 2) / (pow(2, octaves) - 1), qRange.lowerBound),
242	                qRange.upperBound)
243	            params.bells.append(
244	                (f: min(max(frequencies[b], bellRange.lowerBound), bellRange.upperBound),
245	                 g: min(max(r[b], -maxGainDB), maxGainDB), q: q))
246	        }
247	
248	        // (c) Levenberg–Marquardt over every placed parameter.
249	        params = refined(params, curve: curve, weights: weights)
250	
251	        // (d) Rounded; a slot under 0.1 dB is off.
252	        let slots = rounded(params.eq)
253	        let r = residual(curve, model(slots), weights)
254	        let total = weights.reduce(0, +)
255	        return Fit(slots: slots, rmsDB: total > 0 ? (cost(r, weights) / total).squareRoot() : 0)
256	    }
