258	    /// AU-126 (c): LM on the weighted residual, a central-difference
259	    /// Jacobian, λ from 1e−2 (÷10 better, ×10 worse), clamped each step, at
260	    /// most `maximumIterations` or a relative cost change under 1e−6.
261	    private static func refined(_ start: Params, curve: [Double], weights: [Double]) -> Params {
262	        let bells = start.bells.count
263	        let root = weights.map { $0.squareRoot() }
264	        func errors(_ v: [Double]) -> [Double] {
265	            let r = residual(curve, model(Params(v, bells: bells).eq), weights)
266	            return r.indices.map { root[$0] * r[$0] }
267	        }
268	        func squares(_ e: [Double]) -> Double { e.reduce(0) { $0 + $1 * $1 } }
269	        var v = Params(start.vector, bells: bells).vector
270	        var e = errors(v)
271	        var current = squares(e)
272	        var lambda = 1e-2
273	        let m = v.count
274	        let n = e.count
275	        for _ in 0..<maximumIterations {
276	            var jacobian = [[Double]](repeating: [Double](repeating: 0, count: m), count: n)
277	            for p in 0..<m {
278	                let h = 1e-3
279	                var plus = v
280	                var minus = v
281	                plus[p] += h
282	                minus[p] -= h
283	                let ep = errors(plus)
284	                let em = errors(minus)
285	                for i in 0..<n { jacobian[i][p] = (ep[i] - em[i]) / (2 * h) }
286	            }
287	            var jtj = [[Double]](repeating: [Double](repeating: 0, count: m), count: m)
288	            var jte = [Double](repeating: 0, count: m)
289	            for i in 0..<n {
290	                for p in 0..<m {
291	                    jte[p] += jacobian[i][p] * e[i]
292	                    for q in 0..<m { jtj[p][q] += jacobian[i][p] * jacobian[i][q] }
293	                }
294	            }
295	            var system = jtj
296	            for p in 0..<m { system[p][p] += lambda * max(jtj[p][p], 1e-9) }
297	            guard let step = solve(system, jte.map { -$0 }) else { break }
298	            let trial = Params(zip(v, step).map { $0 + $1 }, bells: bells).vector
299	            let te = errors(trial)
300	            let cost = squares(te)
301	            if cost < current {
302	                let change = (current - cost) / max(current, 1e-30)
303	                v = trial
304	                e = te
305	                current = cost
306	                lambda /= 10
307	                if change < 1e-6 { break }
308	            } else {
309	                lambda *= 10
310	                if lambda > 1e12 { break }
311	            }
312	        }
313	        return Params(v, bells: bells)
314	    }
