316	    /// Gaussian elimination with partial pivoting; nil when singular.
317	    private static func solve(_ a: [[Double]], _ b: [Double]) -> [Double]? {
318	        let n = b.count
319	        var m = a
320	        var y = b
321	        for c in 0..<n {
322	            var pivot = c
323	            for r in c + 1..<n where abs(m[r][c]) > abs(m[pivot][c]) { pivot = r }
324	            guard abs(m[pivot][c]) > 1e-15 else { return nil }
325	            m.swapAt(c, pivot)
326	            y.swapAt(c, pivot)
327	            for r in c + 1..<n {
328	                let f = m[r][c] / m[c][c]
329	                guard f != 0 else { continue }
330	                for k in c..<n { m[r][k] -= f * m[c][k] }
331	                y[r] -= f * y[c]
332	            }
333	        }
334	        var x = [Double](repeating: 0, count: n)
335	        for r in stride(from: n - 1, through: 0, by: -1) {
336	            var total = y[r]
337	            for k in r + 1..<n { total -= m[r][k] * x[k] }
338	            x[r] = total / m[r][r]
339	        }
340	        return x
341	    }
