343	    /// AU-126 (d): f to 1 Hz, gain to 0.1 dB, Q to 0.01; |gain| < 0.1 dB off.
344	    static func rounded(_ eq: EqProps) -> EqProps {
345	        func gain(_ g: Double) -> Double? {
346	            let r = (g * 10).rounded() / 10
347	            return abs(r) < 0.1 ? nil : r
348	        }
349	        func shelf(_ s: EqShelfProps?) -> EqShelfProps? {
350	            guard let s, let g = gain(s.gainDb) else { return nil }
351	            return EqShelfProps(frequency: s.frequency.rounded(), gainDb: g)
352	        }
353	        func bell(_ s: EqBandProps?) -> EqBandProps? {
354	            guard let s, let g = gain(s.gainDb) else { return nil }
355	            return EqBandProps(
356	                frequency: s.frequency.rounded(), gainDb: g, q: (s.q * 100).rounded() / 100)
357	        }
358	        let bells = [bell(eq.band1), bell(eq.band2), bell(eq.band3)].compactMap { $0 }
359	        return EqProps(
360	            lowShelf: shelf(eq.lowShelf), band1: bells.count > 0 ? bells[0] : nil,
361	            band2: bells.count > 1 ? bells[1] : nil, band3: bells.count > 2 ? bells[2] : nil,
362	            highShelf: shelf(eq.highShelf))
363	    }
