396	/// The Measuring Sound sheet (road map "audio" AP6, spec §11 AU-65): up
397	/// while a `LoudnessMeasureRun` renders its clips through their chains
398	/// (AU-64), or an `AudioMatchRun` its reference and targets (AU-128), so the
399	/// window never beach-balls on a long clip. It takes any
400	/// `AudioMeasureRunning`, held as the four closures below.
401	/// `AudioSyncSheetController`'s shape: a bar, "Clip n of N…" and Cancel.
402	///
403	/// The run was built on the main thread from what the press read; the sheet
404	/// starts it when it appears. While the sheet is attached every editor action
405	/// validates false (`EditorViewController.validateUserInterfaceItem`), the
406	/// bargain Synchronize Audio strikes. When the outcome comes back the sheet
407	/// keeps it and dismisses itself; `finished` is called once, on the main
408	/// queue's next turn after `viewDidDisappear`. Cancel stops the render in
409	/// flight, releases the run's render wants and dismisses at once: nothing
410	/// changes.
411	final class AudioMeasureSheetController: NSViewController {
412	    /// The run, type-erased: `begin` sets its progress and starts it,
413	    /// answering whether an outcome came back (kept for `deliver`).
414	    private let begin: (@escaping (Int, Int) -> Void, @escaping (Bool) -> Void) -> Void
415	    private let cancelRun: () -> Void
416	    private let finishRun: () -> Void
417	    private let deliver: () -> Void
418	    private let sheetTitle: String
419	
420	    private let bar = NSProgressIndicator()
421	    private let statusLabel = NSTextField(wrappingLabelWithString: "")
422	    /// Set in `loadView`; implicitly unwrapped for exactly that reason
423	    /// (app/CLAUDE.md).
424	    private var cancelButton: NSButton!
425	    private var hiddenButton: NSButton!
426	
427	    private var didStart = false
428	    private var cancelled = false
429	    private var answered = false
430	    private var hasOutcome = false
431	
432	    init<Run: AudioMeasureRunning>(
433	        run: Run, title: String, finished: @escaping (Run.Outcome) -> Void
434	    ) {
435	        let box = AudioMeasureOutcomeBox<Run.Outcome>()
436	        begin = { progress, answered in
437	            run.progress = progress
438	            run.start { outcome in
439	                box.outcome = outcome
440	                answered(outcome != nil)
441	            }
442	        }
443	        cancelRun = { run.cancel() }
444	        finishRun = { run.finish() }
445	        deliver = {
446	            guard let outcome = box.outcome else { return }
447	            finished(outcome)
448	        }
449	        self.sheetTitle = title
450	        super.init(nibName: nil, bundle: nil)
451	    }
452	
453	    @available(*, unavailable)
454	    required init?(coder: NSCoder) {
455	        fatalError("AudioMeasureSheetController does not support NSCoder")
456	    }
457	
458	    override func loadView() {
459	        styleSheetProgressBar(bar, indeterminate: true)
460	
461	        styleSheetStatusLabel(statusLabel)
462	        statusLabel.stringValue = "Measuring the sound through each clip's processing…"
463	
464	        let content = makeProgressStack([bar, statusLabel])
465	
466	        cancelButton = StickerButton(
467	            title: "Cancel", style: .secondary, target: self, action: #selector(cancelClicked(_:)))
468	        hiddenButton = StickerButton(title: "Apply", style: .primary, target: nil, action: nil)
469	        hideReturnTarget(hiddenButton)
470	
471	        view = makeSheetView(
472	            title: sheetTitle,
473	            hint: "Nothing changes until every clip is measured; Cancel leaves everything as "
474	                + "it is.",
475	            content: content, buttonRow: makeButtonRow(cancel: cancelButton, apply: hiddenButton))
476	    }
477	
478	    override func viewDidAppear() {
479	        super.viewDidAppear()
480	        guard !didStart else { return }
481	        didStart = true
482	        bar.startAnimation(nil)
483	        begin({ [weak self] clip, count in
484	            self?.statusLabel.stringValue = "Clip \(clip) of \(count)…"
485	        }) { [weak self] answered in
486	            guard let self, !self.cancelled else { return }
487	            guard answered else {
488	                self.cancelled = true
489	                self.finishRun()
490	                self.dismiss(self)
491	                return
492	            }
493	            self.hasOutcome = true
494	            self.dismiss(self)
495	        }
496	    }
497	
498	    /// The one hand-back: once, with the outcome, and never after Cancel. On
499	    /// the next turn of the main queue, because while this runs the window
500	    /// still reports this sheet as attached.
501	    override func viewDidDisappear() {
502	        super.viewDidDisappear()
503	        bar.stopAnimation(nil)
504	        guard !answered, !cancelled, hasOutcome else { return }
505	        answered = true
506	        let deliver = self.deliver
507	        DispatchQueue.main.async { deliver() }
508	    }
509	
510	    @objc private func cancelClicked(_ sender: Any?) {
511	        guard !cancelled, !hasOutcome else { return }
512	        cancelled = true
513	        cancelRun()
514	        finishRun()
515	        dismiss(self)
516	    }
517	}
