520	/// The one body the Volume section's buttons and the Clip menu share for
521	/// Normalize and Enhance Voice (road map "audio" AP6, spec §11 AU-60,
522	/// AU-64, AU-65), and Clip ▸ Match Audio…'s after its sheet (AP12,
523	/// `pressMatch`, AU-128). Not a line of arithmetic is here: the read, the
524	/// jobs and the plan are `AudioNormalize`'s, `AudioEnhance`'s and
525	/// `AudioMatch`'s, the measurement is `LoudnessMeasureRun`'s or
526	/// `AudioMatchRun`'s, and this decides only how a press waits and commits.
527	///
528	/// - **Normalize in Peak mode** commits `AudioNormalize.plan(read).ops` at
529	///   once, inside the event, exactly as before: no run, no render, no sheet.
530	/// - **Normalize in Loudness mode and Enhance Voice** build a run. When no
531	///   clip needs a render the run answers at once and the plan is committed
532	///   inside the event (`applyEdit`), today's Normalize byte for byte.
533	///   Otherwise the Measuring Sound sheet goes up from the window's content
534	///   controller, and its answer is committed with `performGroupedEdit` (a
535	///   sheet's completion is not an AppKit event, app/CLAUDE.md's undo
536	///   pitfall) only when the document's project and scope are still the ones
537	///   the press read; else it beeps and says so at the inspector's foot, as
538	///   `finishSynchronizeAudio` does.
539	///
540	/// Nothing to do, a second press, no window and a sheet already up all beep.
541	///
542	/// **A landing's follow** (spec §11 AU-68) is another caller:
543	/// `enhanceLanded`, Enhance Voice over a recording's voice clips once their
544	/// caches exist. It shares `measure`, with a refusal at the inspector's foot
545	/// wherever a press beeps, and commits as its own group, since a timer's
546	/// firing is not an AppKit event either.
547	enum AudioMeasureDoor {
548	    enum Command {
549	        case normalize, enhanceVoice, matchAudio
550	
551	        var name: String {
552	            switch self {
553	            case .normalize: return "Normalize"
554	            case .enhanceVoice: return AudioEnhance.actionName
555	            case .matchAudio: return AudioMatch.actionName
556	            }
557	        }
558	
559	        var tool: String {
560	            switch self {
561	            case .normalize: return "normalize_clip"
562	            case .enhanceVoice: return "enhance_voice"
563	            case .matchAudio: return "match_audio"
564	            }
565	        }
566	    }
567	
568	    /// The sheet's title.
569	    static let sheetTitle = "Measuring Sound"
570	
571	    /// The stale answer's sentence, ending in what to do again: "Choose
572	    /// Enhance Voice again." from the sheet, "Call enhance_voice again." from
573	    /// a tool.
574	    static func staleReason(again: String) -> String {
575	        "the project changed while its sound was being measured, so nothing changed. \(again)"
576	    }
577	
578	    static func press(
579	        _ command: Command, document: ProjectDocument, clips: [UInt32], window: NSWindow?
580	    ) {
581	        guard !clips.isEmpty else { return NSSound.beep() }
582	        switch command {
583	        case .normalize where NormalizeChoice.mode == .peak:
584	            guard let input = AudioNormalize.read(from: document, clips: clips) else {
585	                return NSSound.beep()
586	            }
587	            commit(command.name, AudioNormalize.plan(input).ops, document: document)
588	        case .normalize:
589	            guard let input = AudioNormalize.readLoudness(from: document, clips: clips) else {
590	                return NSSound.beep()
591	            }
592	            let target = NormalizeChoice.targetLUFS
593	            let run = LoudnessMeasureRun(
594	                document: document, jobs: normalizeJobs(input, in: document),
595	                problems: input.problems, targetLUFS: target)
596	            measure(command, run: run, document: document, window: window) {
597	                AudioNormalize.plan($0.input, targetLUFS: target, solved: $0.solved).ops
598	            }
599	        case .enhanceVoice:
600	            guard let input = AudioEnhance.read(from: document, clips: clips) else {
601	                return NSSound.beep()
602	            }
603	            let target = NormalizeChoice.targetLUFS
604	            let choices = AudioEnhance.choose(input)
605	            let run = LoudnessMeasureRun(
606	                document: document, jobs: AudioEnhance.jobs(input, choices),
607	                problems: input.problems, targetLUFS: target)
608	            measure(command, run: run, document: document, window: window) {
609	                AudioEnhance.plan(input, choices: choices, outcome: $0, targetLUFS: target).ops
610	            }
611	        case .matchAudio:
612	            // Its reference comes from the Match Audio sheet: `pressMatch`.
613	            NSSound.beep()
614	        }
615	    }
616	
617	    /// Match Audio's press (road map "audio" AP12, spec §11 AU-121, AU-128),
618	    /// from the Match Audio sheet's hand-back: `reference` and the other
619	    /// clips, read, then always measured under the Measuring Sound sheet (the
620	    /// reference renders), its plan committed by `measure`'s stale test. A
621	    /// refusal — the reference's, or nothing to match — beeps and puts its
622	    /// sentence at the inspector's foot, before the sheet or after it.
623	    static func pressMatch(
624	        document: ProjectDocument, reference: UInt32, clips: [UInt32], loudness: Bool, eq: Bool,
625	        window: NSWindow?
626	    ) {
627	        guard loudness || eq, !clips.isEmpty else { return NSSound.beep() }
628	        let input: AudioMatch.Input
629	        switch AudioMatch.read(
630	            from: document, reference: reference, clips: clips, loudness: loudness, eq: eq)
631	        {
632	        case .failure(let refusal): return refuse(refusal.sentence, document: document)
633	        case .success(let read): input = read
634	        }
635	        let run = AudioMatchRun(document: document, input: input)
636	        measure(.matchAudio, run: run, document: document, window: window) { [weak document] in
637	            if let refusal = $0.refusal {
638	                if let document { refuse(refusal.sentence, document: document) }
639	                return []
640	            }
641	            let plan = AudioMatch.plan(input, outcome: $0)
642	            guard !plan.matched.isEmpty else {
643	                // Every target skipped after the renders: the tool's sentence.
644	                if let document {
645	                    refuse(AudioMatch.nothingMatched(plan.skipped), document: document)
646	                }
647	                return []
648	            }
649	            return plan.ops
650	        }
651	    }
652	
653	    /// A beep and `reason` at the inspector's foot.
654	    private static func refuse(_ reason: String, document: ProjectDocument) {
655	        NSSound.beep()
656	        NotificationCenter.default.post(
657	            name: .projectDocumentDidRefuse, object: document,
658	            userInfo: ["refusal": ReelRefusal(op: Command.matchAudio.tool, reason: reason)])
659	    }
660	
661	    /// Enhance Voice over a landed recording's voice clips (AU-68 (e)), at
662	    /// Normalize's target: the press's `measure` with refusals in place of
663	    /// beeps, nothing called back. Main.
664	    static func enhanceLanded(document: ProjectDocument, clips: [UInt32], window: NSWindow) {
665	        let refuse = { (reason: String) in RecordingEnhance.refuse(reason, in: document) }
666	        guard let input = AudioEnhance.read(from: document, clips: clips) else {
667	            return refuse(
668	                "The project's audio plan could not be read, so there is no voice to measure.")
669	        }
670	        guard !input.isEmpty else { return refuse(nothingReason(input.problems)) }
671	        let target = NormalizeChoice.targetLUFS
672	        let choices = AudioEnhance.choose(input)
673	        let run = LoudnessMeasureRun(
674	            document: document, jobs: AudioEnhance.jobs(input, choices),
675	            problems: input.problems, targetLUFS: target)
676	        let plan = { (outcome: LoudnessMeasureRun.Outcome) in
677	            AudioEnhance.plan(input, choices: choices, outcome: outcome, targetLUFS: target)
678	        }
679	        measure(
680	            .enhanceVoice, run: run, document: document, window: window, refuse: refuse,
681	            empty: { nothingReason(plan($0).skipped) }
682	        ) { plan($0).ops }
683	    }
684	
685	    /// `enhance_voice`'s sentence for nothing measured or nothing planned.
686	    static func nothingReason(_ problems: [AudioNormalize.Problem]) -> String {
687	        "Nothing could be enhanced. " + problems.map { $0.description }.joined(separator: " ")
688	    }
689	
690	    /// Loudness Normalize's jobs: a clip whose chain has a stage the cache
691	    /// leaves out renders with no change to its settings (the run takes its
692	    /// limiter off for R0); any other reading stands (AU-64 (a)). Main.
693	    static func normalizeJobs(_ input: AudioNormalize.LoudnessInput, in document: ProjectDocument)
694	        -> [LoudnessMeasureRun.Job]
695	    {
696	        let snapshot = document.editedProject.snapshot
697	        return input.readings.map {
698	            LoudnessMeasureRun.Job(
699	                reading: $0,
700	                chain: ProcessedLoudness.needsRender(snapshot.clip($0.clip)?.audio)
701	                    ? AudioPatch() : nil)
702	        }
703	    }
704	
705	    /// Runs `run` at once when nothing renders, else under the sheet, and
706	    /// commits `ops` of its outcome. With `refuse` (a landing's follow) each
707	    /// beep is that refusal instead — `empty` says why nothing was planned —
708	    /// and the commit is grouped.
709	    private static func measure<Run: AudioMeasureRunning>(
710	        _ command: Command, run: Run, document: ProjectDocument,
711	        window: NSWindow?, refuse: ((String) -> Void)? = nil,
712	        empty: ((Run.Outcome) -> String)? = nil,
713	        ops: @escaping (Run.Outcome) -> [ReelOp]
714	    ) {
715	        let stopped = "\(command.tool) was stopped while its sound was being measured."
716	        guard run.needsRender else {
717	            // No render: the run answers before `start` returns, inside the event.
718	            run.start { outcome in
719	                guard let outcome else { return fail(refuse, stopped) }
720	                guard let refuse else {
721	                    return commit(command.name, ops(outcome), document: document)
722	                }
723	                let planned = ops(outcome)
724	                guard !planned.isEmpty else { return refuse(empty?(outcome) ?? stopped) }
725	                document.performGroupedEdit(command.name, planned)
726	            }
727	            run.finish()
728	            return
729	        }
730	        guard let window, window.attachedSheet == nil, let host = window.contentViewController
731	        else {
732	            run.finish()
733	            return fail(refuse, "A sheet was already up on the project's window, so nothing changed.")
734	        }
735	        let asked = document.project
736	        let scope = document.scope
737	        host.presentAsSheet(
738	            AudioMeasureSheetController(run: run, title: sheetTitle) { [weak document] outcome in
739	                defer { run.finish() }
740	                guard let document else { return }
741	                guard document.project === asked, document.scope == scope else {
742	                    if let refuse { return refuse(staleReason(again: "Choose \(command.name) again.")) }
743	                    NSSound.beep()
744	                    NotificationCenter.default.post(
745	                        name: .projectDocumentDidRefuse, object: document,
746	                        userInfo: [
747	                            "refusal": ReelRefusal(
748	                                op: command.tool,
749	                                reason: staleReason(again: "Choose \(command.name) again."))
750	                        ])
751	                    return
752	                }
753	                let planned = ops(outcome)
754	                guard !planned.isEmpty else { return fail(refuse, empty?(outcome) ?? stopped) }
755	                document.performGroupedEdit(command.name, planned)
756	            })
757	    }
758	
759	    /// The press beeps; a landing's follow says `reason` at the inspector's foot.
760	    private static func fail(_ refuse: ((String) -> Void)?, _ reason: String) {
761	        guard let refuse else { return NSSound.beep() }
762	        refuse(reason)
763	    }
764	
765	    /// Inside the event: `applyEdit`, which beeps at an identity; an empty
766	    /// list beeps here.
767	    private static func commit(_ name: String, _ ops: [ReelOp], document: ProjectDocument) {
768	        guard !ops.isEmpty else { return NSSound.beep() }
769	        document.applyEdit(name, ops)
770	    }
771	}
