774	/// `match_audio` — the agent's mirror of Clip ▸ Match Audio… (road map
775	/// "audio" AP12, spec §11 AU-120…AU-128; `EditorViewController.matchAudio`,
776	/// its sheet's hand-back pressing `AudioMeasureDoor.pressMatch`).
777	///
778	/// An APP-STATE composite like `enhance_voice`, for its reason: what it
779	/// measures is the loudness and speech caches and the clips rendered as they
780	/// play, none of which is in the model, so `OP_NAMES` is untouched and what
781	/// reaches the document is one ordinary `set_audio` per target. It takes no
782	/// `scope`: it follows the open container. Not a line of the arithmetic is
783	/// here — `AudioMatch.read` and `plan` and an `AudioMatchRun`, the menu's
784	/// own — and it is an off-main tool (`AgentServer.offMainTools`): the read,
785	/// the run's start and the commit are on main, the wait
786	/// (`awaitMeasurement`) here.
787	extension AgentServer {
788	
789	    /// The reference's loudness, then each target's row: `set` (exactly the
790	    /// patch's keys in `set_audio`'s spelling), the EQ and its fit, and
791	    /// Normalize's figures for the volume; the skips by name. A second
792	    /// identical call is an identity: "Match Audio made no change".
793	    func matchAudio(_ a: [String: Any]) throws -> String {
794	        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
795	        try requireServerThread("match_audio")
796	        struct Read {
797	            let document: ProjectDocument
798	            let input: AudioMatch.Input
799	            let run: AudioMatchRun
800	            let asked: ReelProject
801	            let scope: UInt32?
802	        }
803	        let read = try onMain { () throws -> Read in
804	            let document = try self.target(a)
805	            let reference = try self.clipArg(a, "reference", document).id
806	            let clips = try self.clipsArg(a, "clips", document)
807	            let loudness = try self.boolArg(a, "loudness") ?? true
808	            let eq = try self.boolArg(a, "eq") ?? true
809	            guard loudness || eq else {
810	                throw ToolError(
811	                    message: "loudness and eq are both false, so there is nothing to match: "
812	                        + "leave one of them true (both are by default).")
813	            }
814	            switch AudioMatch.read(
815	                from: document, reference: reference, clips: clips, loudness: loudness, eq: eq)
816	            {
817	            case .failure(let refusal): throw ToolError(message: refusal.sentence)
818	            case .success(let input):
819	                return Read(
820	                    document: document, input: input,
821	                    run: AudioMatchRun(document: document, input: input),
822	                    asked: document.project, scope: document.scope)
823	            }
824	        }
825	        let outcome = awaitMeasurement(read.run, stop: stop)
826	        return try onMain {
827	            defer { read.run.finish() }
828	            let outcome = try self.measuredOutcome(
829	                outcome, document: read.document, asked: read.asked, scope: read.scope,
830	                tool: "match_audio")
831	            if let refusal = outcome.refusal { throw ToolError(message: refusal.sentence) }
832	            let plan = AudioMatch.plan(read.input, outcome: outcome)
833	            guard !plan.matched.isEmpty else {
834	                throw ToolError(message: AudioMatch.nothingMatched(plan.skipped))
835	            }
836	            return try self.matchAnswer(
837	                plan, input: read.input, referenceLUFS: outcome.referenceLUFS,
838	                document: read.document)
839	        }
840	    }
841	
842	    /// The answer to `plan`, on main: the reference, the rows, the skips,
843	    /// the ceiling's note and the edit.
844	    private func matchAnswer(
845	        _ plan: AudioMatch.Plan, input: AudioMatch.Input, referenceLUFS: Double,
846	        document: ProjectDocument
847	    ) throws -> String {
848	        let reference = input.reference
849	        let speech = reference.speech.map { mask in
850	            Double(mask.filter { $0 }.count) * AudioLimiterModel.stepSeconds
851	        }
852	        var fields: [String: Any] = [
853	            "reference": [
854	                "clip": Int(reference.clip),
855	                "media": Int(reference.media),
856	                "lufs": Self.jsonLevel(referenceLUFS),
857	                "speech_seconds": speech.map { $0 as Any } ?? NSNull(),
858	            ] as [String: Any],
859	            "target_lufs": plan.targetLUFS.map(Self.jsonLevel) ?? NSNull(),
860	            "matched": plan.matched.map(Self.matchedRow),
861	        ]
862	        if !plan.skipped.isEmpty {
863	            fields["skipped"] = plan.skipped.map { $0.description }
864	        }
865	        let limited = plan.matched.filter { $0.loudness?.limit != nil }
866	        if !limited.isEmpty, let target = plan.targetLUFS {
867	            let ids = limited.map { String($0.clip) }.joined(separator: ", ")
868	            fields["note"] =
869	                "Clip(s) \(ids) stopped short of \(target) LUFS: the volume that reaches it "
870	                + "would pass the \(AudioNormalize.maxGainName) ceiling (limited_by max_gain). "
871	                + "result_lufs says where each landed."
872	        }
873	        return try editResult(document, AudioMatch.actionName, plan.ops, fields)
874	    }
875	
876	    /// One target's row of the answer.
877	    private static func matchedRow(_ row: AudioMatch.Row) -> [String: Any] {
878	        func level(_ value: Double?) -> Any { value.map(jsonLevel) ?? NSNull() }
879	        let loudness = row.loudness
880	        return [
881	            "clip": Int(row.clip),
882	            "media": Int(row.media),
883	            "set": row.set.dictionary,
884	            "eq": row.eq.map { $0.dictionary as Any } ?? NSNull(),
885	            "eq_fit_rms_db": level(row.fitRMSDB),
886	            "volume": loudness.map { $0.volume as Any } ?? NSNull(),
887	            "measured_lufs": level(loudness?.measuredLUFS),
888	            "processed_lufs": level(loudness?.processedLUFS),
889	            "result_lufs": level(loudness?.resultLUFS),
890	            "result_true_peak_dbtp": level(loudness?.resultTruePeakDBTP),
891	            "limited_by": loudness?.limit.map { $0.rawValue as Any } ?? NSNull(),
892	            "renders": (loudness?.renders ?? 0) + (row.eq != nil ? 1 : 0),
893	        ]
894	    }
895	}
