    /// mute and fades multiply what is under it. Normalize is the one that
    /// cannot be: the plan flattens a nest, so the clip has no segment of its
    /// own and `read` can only refuse it. A command that can only refuse is a
    /// command that should not be enabled (the same rule the Normalize
    /// validator arm was added for in the first place), and the answer lives
    /// HERE so the button and the menu item cannot answer it differently.
    ///
    /// It is a cheap PRE-check and not a promise: a clip it says yes about can
    /// still be refused by `read` — no peaks yet, silence, `enabled.audio` off
    /// up the chain — and being told why is better than a greyed control. That
    /// is the right side to be wrong on, and it is why this asks the snapshot
    /// while `read` asks the plan.
    static func canOffer(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        guard InspectorTab.hasAudio(clip, in: snapshot) else { return false }
        if case .nest = clip.source { return false }
        return true
    }

    // MARK: - Reading

    /// Reads a document's snapshot, plan and peak caches for `clips`.
    ///
    /// `clips` is the caller's list — the pane passes the selected clips that
    /// carry audio, the tool passes its `clips` argument. nil takes the
    /// document's own selection, which is the sheet-less equivalent of
    /// `SilenceDetector.read`'s selection override.
    ///
    /// nil is answered only when the core emitted a plan this build cannot
    /// read — the same failure `CompositionBuilder` treats as fatal. A clip
    /// that simply cannot be normalised is a `Problem`, not a nil.
    static func read(from document: ProjectDocument, clips: [UInt32]? = nil) -> Input? {
        // The EDITED project: a clip inside a nest is normalised against the
        // plan of the project it is IN, which is the only one holding an
        // audio segment for it (road map 2's phase 9).
        guard let plan = document.editedProject.plan else { return nil }
        let snapshot = document.editedProject.snapshot
        let loader = MediaPeaks.loader(cacheDirectory: document.cacheDirectory)
        let segments = audioSegments(in: plan)

        var readings: [Reading] = []
        var problems: [Problem] = []
            for segment in track.segments where segment.duration > 0 {
                segments[segment.clip, default: []].append(segment)
            }
        }
        return segments
    }

    /// Whether `id` can be measured at all, in either mode: nil when it can,
    /// else the refusal by name — not a clip, a nest, no audio segment, no
    /// audio props. What is read off the cache after this is each mode's own.
    static func admit(
        _ id: UInt32, in snapshot: ProjectSnapshot, segments: [UInt32: [PlanSegment]]
    ) -> Problem? {
        guard let clip = snapshot.clip(id) else {
            return Problem(clip: id, reason: "is not a clip in this project.")
        }
        // A nest is refused HERE rather than by the segment test below,
        // and the reason is the message. A nest clip is audible — its own
        // volume and mute multiply every voice under it (`audio.rs`) — but
        // the plan flattens it, so every segment it plays carries an INNER
        // clip's id and `segments[id]` is empty for the nest itself. The
        // generic refusal would therefore say "plays no sound in this
        // timeline" about a clip the user can hear, which is the one thing
        // a refusal must not do; and there is no level to measure anyway,
        // because the peaks cache is per MEDIA and a nest holds clips that
        // each have their own.
        if case .nest = clip.source {
            return Problem(
                clip: id,
                reason: "is a nest, and a nest has no level of its own to measure: the "
                    + "waveform cache is per media file and the clips inside a nest "
                    + "each have their own. Un-nest it (⇧⌘G), normalize the clips "
                    + "inside, and nest them again — or set the nest clip's own volume "
                    + "by hand.")
        }
        guard let cited = segments[id], !cited.isEmpty else {
            return Problem(
                clip: id,
                reason: "plays no sound in this timeline, so there is no level to "
                    + "measure. A still, a clip whose media has no audio track and a "
                    + "clip with audio switched off all read this way.")
        }
        // The core refuses `set_audio` on a clip with no audio group by
        // name ("clip N has no audio properties"), and that message would
        // otherwise reach a dialog from a button press. It cannot happen
        // for a clip that has a segment — `add_clip` gives an audio group
        // to exactly the clips whose media has sound — but a project is
        // JSON somebody may have edited, and the pre-check costs a line.
        guard clip.audio != nil else {
            return Problem(clip: id, reason: "has no audio properties to write a volume into.")
        }
        return nil
    }

    // MARK: - Planning


    // MARK: - Planning

    /// AU-24: `v0 = min(10^((T−L)/20), maxGain)`. A clip with no limiter whose
    /// true peak fits the ceiling at `v0` gets `volume: v0` alone (AP1's
    /// result). Any other gets one `set_audio {volume, limiter}`: its own
    /// limiter kept, the ceiling lowered to −1 dBTP when above it, or the
    /// default; the volume is `AudioLimiterModel`'s gain for the target under
    /// that limiter. `limited_by` is `max_gain` when the volume ceiling stops
    /// it short. It may turn a clip down. A non-finite target falls back to
    /// the default and is reported as `targetLUFS`. A clip in `solved` was
    /// measured through its chain (AU-64) and takes its solve's volume and
    /// limiter instead (`solvedRow`).
    static func plan(
        _ input: LoudnessInput, targetLUFS: Double = defaultTargetLUFS,
        solved: [UInt32: Solved] = [:]
    ) -> LoudnessPlan {
        let target = targetLUFS.isFinite ? targetLUFS : defaultTargetLUFS
        let ceiling = pow(10, ceilingDBTP / 20)
        var ops: [ReelOp] = []
        var normalized: [LoudnessResult] = []
        for reading in input.readings {
            if let solve = solved[reading.clip] {
                let (op, row) = solvedRow(reading, solve)
                ops.append(op)
                normalized.append(row)
                continue
            }
            let wanted = pow(10, (target - reading.lufs) / 20)
            let first = max(0, min(wanted, maxGain))
            let row: LoudnessResult
            if reading.limiter == nil, reading.truePeak * first <= ceiling {
                ops.append(.setAudio(clips: [reading.clip], patch: AudioPatch(volume: first)))
                row = LoudnessResult(
                    clip: reading.clip, media: reading.media, measuredLUFS: reading.lufs,
                    truePeakDBTP: 20 * log10(reading.truePeak), volume: first,
                    resultLUFS: reading.lufs + 20 * log10(first),
                    resultTruePeakDBTP: 20 * log10(reading.truePeak * first),
                    limit: wanted <= maxGain ? nil : .maxGain, limiter: nil)
            } else {
                var limiter = reading.limiter ?? LimiterProps()
                limiter.ceilingDb = min(limiter.ceilingDb, ceilingDBTP)
                let solved = solve(reading, target: target, wanted: first, limiter: limiter)
                ops.append(
                    .setAudio(
                        clips: [reading.clip],
                        patch: AudioPatch(volume: solved.volume, limiter: .some(limiter))))
                row = LoudnessResult(
                    clip: reading.clip, media: reading.media, measuredLUFS: reading.lufs,
                    truePeakDBTP: 20 * log10(reading.truePeak), volume: solved.volume,
                    resultLUFS: solved.lufs,
                    resultTruePeakDBTP: 20 * log10(
                        min(reading.truePeak * solved.volume, pow(10, limiter.ceilingDb / 20))),
                    limit: solved.lufs < target - AudioLimiterModel.tolerance ? .maxGain : nil,
                    limiter: limiter)
            }
            normalized.append(row)
        }
        return LoudnessPlan(
            targetLUFS: target, ops: ops, normalized: normalized, skipped: input.problems)
    }

    /// A rendered clip's op and row (AU-64 (e), (f)): the solve's volume,
    /// or the clip's own when it already carries the solved limiter and the
    /// two are within `keepVolumeDB`, so a second press is an identity.
    private static func solvedRow(_ reading: LoudnessReading, _ solve: Solved)
        -> (ReelOp, LoudnessResult)
    {
        var volume = solve.volume
        if solve.limiter == reading.limiter, let current = reading.currentVolume, current > 0,
            solve.volume > 0, abs(20 * log10(solve.volume / current)) <= keepVolumeDB
        {
            volume = current
        }
        let patch = solve.limiter.map { AudioPatch(volume: volume, limiter: .some($0)) }
            ?? AudioPatch(volume: volume)
        var row = LoudnessResult(
            clip: reading.clip, media: reading.media,
            measuredLUFS: reading.materialLUFS ?? reading.lufs,
            truePeakDBTP: 20 * log10(reading.truePeak), volume: volume,
            resultLUFS: solve.resultLUFS, resultTruePeakDBTP: solve.resultTruePeakDBTP,
            limit: solve.limit, limiter: solve.limiter)
        row.processedLUFS = reading.lufs
        row.renders = solve.renders
        return (.setAudio(clips: [reading.clip], patch: patch), row)
    }

