107	    /// a leveller or a de-esser on the base or keyed on at any action's end
108	    /// (AU-88).
109	    static func wanting(_ snapshot: ProjectSnapshot) -> [ClipSnapshot] {
110	        func ended(_ clip: ClipSnapshot) -> Bool {
111	            clip.actions.contains {
112	                if case .some(.some) = $0.end.audio?.gate { return true }
113	                if case .some(.some) = $0.end.audio?.leveller { return true }
114	                if case .some(.some) = $0.end.audio?.deEsser { return true }
115	                return false
116	            }
117	        }
