125	    /// Every wanting clip's level; empty, with no plan decoded, when no clip
126	    /// wants one.
127	    func levels(for project: ReelProject, cache: URL?) -> [UInt32: Level] {
128	        let snapshot = project.snapshot
129	        let wanted = Self.wanting(snapshot)
130	        guard !wanted.isEmpty else { return [:] }
131	        guard let cache else {
132	            return Dictionary(uniqueKeysWithValues: wanted.map { ($0.id, .pending) })
133	        }
134	        let key = Key(cache: cache.standardizedFileURL.path, plan: project.planJSON)
135	
136	        var result: [UInt32: Level] = [:]
137	        var missing: [ClipSnapshot] = []
138	        lock.lock()
139	        let held = memo[key] ?? [:]
140	        lock.unlock()
141	        for clip in wanted {
142	            if let entry = held[clip.id], entry.matrix == ClipLoudness.ChannelMatrix(clip.audio) {
143	                result[clip.id] = entry.level
144	            } else {
145	                missing.append(clip)
146	            }
147	        }
148	        guard !missing.isEmpty else { return result }
149	
150	        let segments = project.plan.map(AudioNormalize.audioSegments(in:)) ?? [:]
151	        let loader = MediaCacheLoader(cacheDirectory: cache) { [weak self] media, url in
152	            self?.file(media: media, cache: key.cache, url: url)
153	        }
154	        var measured: [UInt32: Entry] = [:]
155	        for clip in missing {
156	            let level = Self.level(
157	                ClipLoudness.answer(
158	                    for: clip.id, snapshot: snapshot, segments: segments, loader: loader))
159	            result[clip.id] = level
160	            guard level != .pending else { continue }
161	            measured[clip.id] = Entry(
162	                matrix: ClipLoudness.ChannelMatrix(clip.audio),
163	                media: segments[clip.id]?.first?.media, level: level)
164	        }
165	        if !measured.isEmpty { remember(measured, under: key) }
166	        return result
