169	    /// Blocks the calling thread (never main) until no clip of `clips` is
170	    /// pending, polling every 0.1 s.
171	    func wait(
172	        for clips: Set<UInt32>, in project: ReelProject, cache: URL?, timeout: TimeInterval,
173	        cancelled: () -> Bool
174	    ) -> WaitResult {
175	        let deadline = Date().addingTimeInterval(timeout)
176	        while true {
177	            let levels = levels(for: project, cache: cache)
178	            let curves = curves(for: project, cache: cache)
179	            let pending = clips.filter {
180	                if case .pending = curves[$0] { return true }
181	                return levels[$0] == .pending
182	            }
183	            guard let first = pending.min() else { return .landed }
184	            if cancelled() { return .cancelled }
185	            if Date() >= deadline { return .timedOut(clip: first) }
186	            Thread.sleep(forTimeInterval: 0.1)
187	        }
188	    }
