192	    private static func level(_ answer: ClipLoudness.Answer) -> Level {
193	        switch answer {
194	        case .pending:
195	            return .pending
196	        case .unavailable:
197	            return .unmeasurable(reason: "it plays no sound in this timeline")
198	        case .reading(let reading):
199	            if let lufs = reading.lufs { return .measured(lufs: lufs) }
200	            return .unmeasurable(
201	                reason: reading.playedTicks < ClipLoudness.minimumPlayedTicks
202	                    ? "it plays for under 0.4 s" : "it is too quiet to measure")
