206	    /// A media's loudness file, read once per cache folder; a miss is not
207	    /// kept.
208	    private func file(media: UInt32, cache: String, url: URL) -> MediaLoudness? {
209	        lock.lock()
210	        let held = files[cache]?[media]
211	        lock.unlock()
212	        if let held { return held }
213	        guard let read = MediaImporter.loadLoudness(for: media, in: url) else { return nil }
214	        lock.lock()
