220	    private func remember(_ entries: [UInt32: Entry], under key: Key) {
221	        lock.lock()
222	        defer { lock.unlock() }
223	        if memo[key] == nil {
224	            order.append(key)
225	            while order.count > Self.memoCap { memo.removeValue(forKey: order.removeFirst()) }
226	        }
227	        memo[key, default: [:]].merge(entries) { _, new in new }
228	    }
