230	    /// A `loudness` or `speech` post for `media`: its curves go, and on a
231	    /// `loudness` post its levels and file too; every open document with a
232	    /// gate, leveller or de-esser on it rebuilds (a leveller alone on a
233	    /// `speech` post). Main thread.
234	    private func cacheChanged(media: UInt32, loudness: Bool) {
235	        lock.lock()
236	        for key in curveMemo.keys {
237	            curveMemo[key] = curveMemo[key]?.filter { $0.value.media != media }
238	        }
239	        if loudness {
240	            for key in memo.keys {
241	                memo[key] = memo[key]?.filter { $0.value.media != media }
242	            }
243	            for cache in files.keys { files[cache]?.removeValue(forKey: media) }
244	        }
245	        lock.unlock()
246	        for case let document as ProjectDocument in NSDocumentController.shared.documents {
247	            // A speech post moves only the leveller's curves.
248	            let snapshot = document.project.snapshot
249	            let clips = loudness ? Self.wanting(snapshot) : Self.levelling(snapshot)
250	            let gated = clips.contains { $0.source.mediaID == media }
251	            guard gated else { continue }
252	            NotificationCenter.default.post(name: .reversedMediaDidChange, object: document)
253	        }
254	    }
