297	    /// Every levelling clip's curves; empty, with no plan decoded, when no
298	    /// clip levels. `speechDetection` is whether a VAD file can still land
299	    /// (read on each call; a probe passes it).
300	    func curves(
301	        for project: ReelProject, cache: URL?, speechDetection: Bool = SileroVAD.isAvailable
302	    ) -> [UInt32: Curves] {
303	        let snapshot = project.snapshot
304	        let wanted = Self.levelling(snapshot)
305	        guard !wanted.isEmpty else { return [:] }
306	        guard let cache else {
307	            return Dictionary(uniqueKeysWithValues: wanted.map { ($0.id, .pending(what: "loudness")) })
308	        }
309	        let key = Key(cache: cache.standardizedFileURL.path, plan: project.planJSON)
310	        var result: [UInt32: Curves] = [:]
311	        var missing: [ClipSnapshot] = []
312	        lock.lock()
313	        let held = curveMemo[key] ?? [:]
314	        lock.unlock()
315	        for clip in wanted {
316	            if let entry = held[clip.id], entry.matrix == ClipLoudness.ChannelMatrix(clip.audio),
317	                entry.speech == entry.media.flatMap({ snapshot.media($0)?.speech }),
318	                entry.responses == Self.responses(clip) {
319	                result[clip.id] = entry.curves
320	            } else {
321	                missing.append(clip)
322	            }
323	        }
324	        guard !missing.isEmpty else { return result }
325	
326	        let segments = project.plan.map(AudioNormalize.audioSegments(in:)) ?? [:]
327	        let loader = MediaCacheLoader(cacheDirectory: cache) { [weak self] media, url in
328	            self?.file(media: media, cache: key.cache, url: url)
329	        }
330	        var made: [UInt32: CurveEntry] = [:]
331	        for clip in missing {
332	            let own = (segments[clip.id] ?? []).filter { $0.media == segments[clip.id]?.first?.media }
333	            let media = own.first.flatMap { snapshot.media($0.media) }
334	            let responses = Self.responses(clip)
335	            let curves = Self.curves(
336	                ClipLoudness.answer(for: clip.id, snapshot: snapshot, segments: segments, loader: loader),
337	                own: own, media: media, cache: cache, responses: responses,
338	                speechDetection: speechDetection)
339	            result[clip.id] = curves
340	            // Neither waiting nor speech detection's absence is kept: each is
341	            // asked again on the next call (AU-66 (e)).
342	            if case .pending = curves { continue }
343	            if curves == .unmeasurable(reason: Self.noSpeechDetection) { continue }
344	            made[clip.id] = CurveEntry(
345	                matrix: ClipLoudness.ChannelMatrix(clip.audio), media: media?.id,
346	                speech: media?.speech, responses: responses, curves: curves)
347	        }
348	        if !made.isEmpty {
349	            lock.lock()
350	            if curveMemo[key] == nil {
351	                curveOrder.append(key)
352	                while curveOrder.count > Self.memoCap {
353	                    curveMemo.removeValue(forKey: curveOrder.removeFirst())
354	                }
355	            }
356	            curveMemo[key, default: [:]].merge(made) { _, new in new }
357	            lock.unlock()
358	        }
359	        return result
360	    }
361	
362	    /// One clip's curves from its loudness answer and its media's spans.
363	    private static func curves(
364	        _ answer: ClipLoudness.Answer, own: [PlanSegment], media: MediaSnapshot?, cache: URL,
365	        responses: Set<Ticks>, speechDetection: Bool
366	    ) -> Curves {
367	        let reading: ClipLoudness.Reading
368	        switch level(answer) {
369	        case .pending: return .pending(what: "loudness")
370	        case .unmeasurable(let reason): return .unmeasurable(reason: reason)
371	        case .measured:
372	            guard case .reading(let read) = answer else { return .pending(what: "loudness") }
373	            reading = read
374	        }
375	        guard let media, let L = reading.lufs else {
376	            return .unmeasurable(reason: "it plays no sound in this timeline")
377	        }
378	        guard let spans = media.speech ?? AudioEnhance.speechSpans(media, cache: cache) else {
379	            return speechDetection
380	                ? .pending(what: "speech") : .unmeasurable(reason: noSpeechDetection)
381	        }
382	        let mask = AudioEnhance.speechMask(sources: reading.stepSources, spans: spans)
383	        var made: [Ticks: AudioLevellerCurve] = [:]
384	        for response in responses {
385	            guard
386	                let curve = AudioLevellerCurve.make(
387	                    reading: reading, segments: own, speech: mask, level: L, response: response)
388	            else { return .unmeasurable(reason: "it has no phrase with 1 s of speech") }
389	            made[response] = curve
390	        }
391	        return .ready(made)
392	    }
393	}
