397	// The noise-reduction stage `AudioDSPChain` runs: a pure move out of `AudioDSP.swift` (road
398	// map "audio" AP0's toll T1), whose head says why the stages have no AVFoundation in them
399	// and what real-time discipline they keep.
400	
401	// MARK: - Noise reduction
402	
403	/// Broadband noise reduction, one instance per channel: a short-time spectral
404	/// attenuator over a noise floor the signal itself is measured for.
405	///
406	/// **What it actually does**, spelled out so that neither this comment nor the
407	/// pane's label can overstate it. The signal is cut into 512-sample frames
408	/// every 128 samples and each is windowed and transformed. A per-bin estimate
409	/// of the background noise floor is tracked continuously. Each bin is then
410	/// multiplied by a Wiener gain — `SNR / (SNR + k)` — over a decision-directed
411	/// estimate of that bin's signal-to-noise ratio, with `k` the over-subtraction
412	/// factor the user's amount sets and a floor under the result so a suppressed
413	/// bin fades rather than vanishes. The frames are windowed again and
414	/// overlap-added back.
415	///
416	/// **It is not a gate, and the difference is the point.** Nothing here
417	/// compares a level with a threshold and decides between "signal" and
418	/// "silence": every bin of every frame keeps the fraction of itself that its
419	/// own SNR says is signal, so a quiet passage keeps its content and a steady
420	/// hiss is attenuated *underneath* speech rather than only between words. What
421	/// it cannot do is remove a noise that is not stationary — a door slam, a
422	/// cough — because nothing distinguishes those from the material.
423	///
424	/// **The noise estimate is continuous minimum tracking** (Doblinger's
425	/// recursive-minimum variant of Martin's minimum statistics): the smoothed
426	/// power in each bin is followed by a value that falls to it instantly and
427	/// rises back only slowly, so it settles on the floor the bin returns to
428	/// between sounds. That needs no noise print from the user and no silence at
429	/// the head of the clip. Its known cost is that a bin which is never quiet —
430	/// a long held note — is eventually read as noise; `minimumRise` is set for
431	/// that case and the decision-directed SNR carries the rest.
432	///
433	/// **Latency.** An STFT cannot see a sample's neighbours before they arrive,
434	/// so the output lags the input by one analysis window: 512 samples, 10.7 ms
435	/// at 48 kHz. Measured, not assumed: a tap's process callback cannot read
436	/// ahead — a second `MTAudioProcessingTapGetSourceAudio` inside one callback
437	/// returns the SAME audio again rather than the next block, so priming a
438	/// look-ahead is impossible. 10.7 ms is far inside every A/V sync tolerance
439	/// and applies only to a track some clip of which asks for noise reduction;
440	/// `AudioTap` keeps the stage running for the whole track once any clip on it
441	/// does, so the delay never changes at a cut.
442	final class AudioNoiseReductionStage {
443	    /// Analysis window, a power of two for `vDSP`'s radix-2 FFT.
444	    static let window = 512
445	    /// Hop: 75 % overlap, which is what a √Hann pair needs to add back up to
446	    /// a constant and is fine enough that a modified bin does not smear.
447	    static let hop = 128
448	
449	    private let log2n: vDSP_Length
450	    private let setup: FFTSetup
451	    private let half: Int
452	
453	    /// √Hann, used for BOTH analysis and synthesis (Griffin–Lim): windowing
454	    /// twice is what keeps a per-bin gain change from clicking at the frame
455	    /// edges.
456	    private let windowCurve: UnsafeMutablePointer<Float>
457	    /// Everything below is allocated once and reused every frame.
458	    private let history: UnsafeMutablePointer<Float>      // last `window` inputs
459	    private let staging: UnsafeMutablePointer<Float>      // this hop's inputs
460	    private let frame: UnsafeMutablePointer<Float>
461	    private let real: UnsafeMutablePointer<Float>
462	    private let imaginary: UnsafeMutablePointer<Float>
463	    private let power: UnsafeMutablePointer<Float>        // half + 1
464	    private let smoothed: UnsafeMutablePointer<Float>     // half + 1
465	    private let minimum: UnsafeMutablePointer<Float>      // half + 1
466	    private let binGain: UnsafeMutablePointer<Float>      // half + 1
467	    /// Last frame's estimate of the CLEAN power per bin, which is what makes
468	    /// the a priori SNR below a decision-directed one rather than a raw
469	    /// per-frame ratio.
470	    private let cleaned: UnsafeMutablePointer<Float>      // half + 1
471	    private let overlap: UnsafeMutablePointer<Float>      // window
472	    /// The finished samples waiting to be handed back, as a plain FIFO with a
473	    /// read and a write index. It never holds more than two hops, and it is
474	    /// compacted on a push rather than shifted on a pop — a `memmove` per
475	    /// SAMPLE is what a naive queue costs here, and this runs on the audio
476	    /// thread.
477	    private let output: UnsafeMutablePointer<Float>       // window + hop
478	    private var outputHead = 0
479	    private var outputTail = 0
480	    private var stagedCount = 0
481	    /// False until the first frame has been analysed. The tracker starts at
482	    /// that frame's own power rather than at zero: from zero it would take
483	    /// its whole rise constant to charge up to the noise floor, and until it
484	    /// did every bin would look like signal and nothing would be removed.
485	    private var primed = false
486	    /// The forward/inverse round trip's scale, times the overlap-add
487	    /// normalisation. Both are constants of the window and the hop, so they
488	    /// are folded into one multiply.
489	    private let scale: Float
490	
491	    /// Smoothing of the per-bin power before the minimum tracker sees it.
492	    private let powerSmoothing: Float = 0.7
493	    /// How fast the tracked minimum may rise back — the one number that
494	    /// decides whether a held note is mistaken for the room.
495	    ///
496	    /// The tracker FALLS instantly and rises at this rate, so an
497	    /// overestimate corrects itself within a few frames of quiet while an
498	    /// underestimate persists. That asymmetry says to be slow: 0.9999 per hop
499	    /// is about 27 s at 48 kHz. Measured on a one-second 700 Hz tone buried
500	    /// in white noise, 0.998 (1.4 s) took 12 dB off the tone and 0.9995 (5 s)
501	    /// took 10 dB, because the tracker climbed to the tone and the filter
502	    /// then read it as the floor; at 0.9999 the tone comes through within
503	    /// half a dB and the noise-only stretches still lose 13.
504	import Accelerate
505	import Foundation
506	
507	/// What one clip's gate asks the stage for, in the stage's units (spec §11
508	/// AU-40, AU-41, AU-43): its threshold in absolute dBFS — the clip's measured
509	/// loudness `level` plus the relative threshold — and its times in seconds.
510	/// A hand-edited value outside the model's ranges is held to them (the
511	/// core's `clamp_gate` says the same).
512	struct AudioGateSettings: Equatable {
513	    let thresholdDB: Double
514	    let ratio: Double
515	    let rangeDB: Double
516	    let attackSeconds: Double
517	    let holdSeconds: Double
518	    let releaseSeconds: Double
519	
520	    init(level: Double, props: GateProps) {
521	        func bounded(_ value: Double, _ low: Double, _ high: Double, _ neutral: Double) -> Double {
522	            value.isNaN ? neutral : Swift.min(Swift.max(value, low), high)
523	        }
524	        func seconds(_ ticks: Ticks, _ low: Ticks, _ high: Ticks) -> Double {
525	            Double(Swift.min(Swift.max(ticks, low), high)) / Double(ReelTime.perSecond)
526	        }
527	        let relative = bounded(props.thresholdDb, -40, 0, -10)
528	        thresholdDB = (level.isFinite ? level : 0) + relative
529	        ratio = bounded(props.ratio, 1, 20, 4)
530	        rangeDB = bounded(props.rangeDb, 1, 80, 20)
531	        attackSeconds = seconds(props.attack, 0, 60_000)
532	        holdSeconds = seconds(props.hold, 0, 300_000)
533	        releaseSeconds = seconds(props.release, 600, 1_200_000)
534	    }
535	}
