537	/// The downward expander/gate (spec §11 AU-40), after noise reduction and
538	/// before the de-esser (AU-47).
539	///
540	/// The detector is the compressor's: the linked peak follower
541	/// (`AudioEnvelope`), falling at its 10 ms floor. Per sample, a level at or
542	/// above the threshold restarts the hold counter and asks for no reduction;
543	/// while the counter runs the gate stays open; after it, the target is
544	/// `min(range, (threshold − level)·(ratio − 1))` dB. The reduction moves
545	/// toward the target by one-pole steps — the attack's coefficient when it
546	/// opens (the target below the reduction), the release's when it closes —
547	/// and one gain multiplies every channel.
548	///
549	/// **Fresh state is OPEN** (no reduction, the follower at 0, no hold), and
550	/// `reset()` restores it; `AudioTap` resets the chain at every StartOfStream,
551	/// so the preview does not start closed off the silent pre-roll (S1).
552	/// Real-time rules (`AudioDSP.swift`'s head): buffers allocated in `init`,
553	/// scalar recursion and element-wise vDSP, chunks at capacity; nil settings
554	/// reset the stage and touch no sample.
555	final class AudioGateStage {
556	    private var reductionDB: Float = 0
557	    private var follower = AudioPeakFollower()
558	    /// Samples the gate stays open for after the level last reached the
559	    /// threshold.
560	    private var holdCounter = 0
561	    private let sampleRate: Double
562	    private let detector: UnsafeMutablePointer<Float>
563	    private let scratch: UnsafeMutablePointer<Float>
564	    private let gains: UnsafeMutablePointer<Float>
565	    private let capacity: Int
566	
567	    init(sampleRate: Double, maxFrames: Int) {
568	        self.sampleRate = sampleRate > 0 ? sampleRate : 48000
569	        capacity = max(1, maxFrames)
570	        detector = .allocate(capacity: capacity)
571	        scratch = .allocate(capacity: capacity)
572	        gains = .allocate(capacity: capacity)
573	        detector.initialize(repeating: 0, count: capacity)
574	        scratch.initialize(repeating: 0, count: capacity)
575	        gains.initialize(repeating: 1, count: capacity)
576	    }
577	
578	    @available(*, unavailable) required init?(coder: NSCoder) {
579	        fatalError("AudioGateStage does not support NSCoder")
580	    }
581	
582	    deinit {
583	        detector.deallocate()
584	        scratch.deallocate()
585	        gains.deallocate()
586	    }
587	
588	    /// A fresh, open gate.
589	    func reset() {
590	        reductionDB = 0
591	        follower.reset()
592	        holdCounter = 0
593	    }
594	
595	    /// Gates `frames` samples in place across `count` channels.
596	    func process(
597	        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
598	        frames: Int, settings: AudioGateSettings?
599	    ) {
600	        guard let settings else {
601	            reset()
602	            return
603	        }
604	        guard frames > 0, count > 0 else { return }
605	        var offset = 0
606	        while offset < frames {
607	            let chunk = min(capacity, frames - offset)
608	            processChunk(channels, count: count, offset: offset, frames: chunk, settings: settings)
609	            offset += chunk
610	        }
611	    }
612	
613	    private func processChunk(
614	        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
615	        offset: Int, frames: Int, settings: AudioGateSettings
616	    ) {
617	        guard
618	            AudioEnvelope.linkedPeaks(
619	                channels, count: count, offset: offset, frames: frames, into: detector,
620	                scratch: scratch)
621	        else { return }
622	
623	        let thresholdDB = Float(settings.thresholdDB)
624	        let thresholdLinear = AudioDSP.gain(fromDecibels: thresholdDB)
625	        let expansion = Float(settings.ratio) - 1
626	        let range = Float(settings.rangeDB)
627	        let attack = AudioEnvelope.coefficient(
628	            seconds: settings.attackSeconds, sampleRate: sampleRate)
629	        let release = AudioEnvelope.coefficient(
630	            seconds: settings.releaseSeconds, sampleRate: sampleRate)
631	        let fall = AudioEnvelope.fall(seconds: 0, sampleRate: sampleRate)
632	        let holdFrames = Int((settings.holdSeconds * sampleRate).rounded())
633	
634	        for index in 0..<frames {
635	            let level = follower.follow(detector[index], fall: fall)
636	            var target: Float = 0
637	            if level >= thresholdLinear {
638	                holdCounter = holdFrames
639	            } else if holdCounter > 0 {
640	                holdCounter -= 1
641	            } else if expansion > 0 {
642	                let levelDB = 20 * log10f(max(level, AudioDSP.silenceFloor))
643	                target = min(range, (thresholdDB - levelDB) * expansion)
644	            }
645	            let coefficient = target < reductionDB ? attack : release
646	            reductionDB += (target - reductionDB) * coefficient
647	            gains[index] = AudioDSP.gain(fromDecibels: -reductionDB)
648	        }
649	
650	        for channel in 0..<count {
651	            guard let data = channels[channel] else { continue }
652	            vDSP_vmul(data + offset, 1, gains, 1, data + offset, 1, vDSP_Length(frames))
653	        }
654	    }
655	}
