659	/// What one clip's de-esser asks the stage for (spec §11 AU-44, AU-45): the
660	/// crossover in Hz, the threshold in absolute dBFS on the sidechain's
661	/// follower — the clip's measured loudness `level` plus the relative
662	/// threshold — and the range. A hand-edited value outside the model's ranges
663	/// is held to them (the core's `clamp_de_esser` says the same).
664	struct AudioDeEsserSettings: Equatable {
665	    let frequency: Double
666	    let thresholdDB: Double
667	    let rangeDB: Double
668	
669	    init(level: Double, props: DeEsserProps) {
670	        func bounded(_ value: Double, _ low: Double, _ high: Double, _ neutral: Double) -> Double {
671	            value.isNaN ? neutral : Swift.min(Swift.max(value, low), high)
672	        }
673	        frequency = bounded(props.frequency, 2000, 12_000, 6000)
674	        thresholdDB = (level.isFinite ? level : 0) + bounded(props.thresholdDb, -30, 20, 0)
675	        rangeDB = bounded(props.rangeDb, 1, 24, 6)
676	    }
677	}
678	
679	/// The split-band de-esser (spec §11 AU-44), after the gate and before the
680	/// compressor (AU-47).
681	///
682	/// **Detection.** A sidechain per channel — a 24 dB/octave Butterworth
683	/// high-pass at `frequency`, two RBJ sections (Q 0.541, 1.307) — then the
684	/// compressor's linked peak follower over it (`AudioEnvelope`, 10 ms fall).
685	/// Above the threshold the target reduction is `min(range, level − threshold)`
686	/// dB (∞:1, never deeper than the range); it closes in 1 ms and opens in
687	/// 60 ms, and `g = 10^(−reduction/20)`.
688	///
689	/// **Reduction, through a Linkwitz–Riley crossover.** The same `frequency`
690	/// splits each channel into `low` (two `lowPass(f, q: 1/√2)` sections) and
691	/// `band` (two `highPass(f, q: 1/√2)`), and the output is `low + g·band`.
692	/// LR4's two outputs are in phase at every frequency and sum to an allpass,
693	/// so `|out/x| = 1 − (1 − g)·|band|`, in `[g, 1]`: no frequency is boosted.
694	/// (`x − (1 − g)·band` would be: a 4th-order Butterworth high-pass is 180°
695	/// out at its cut.) At `g = 1` the output is x's allpass — flat, but not x's
696	/// bytes. All six sections are redesigned when the frequency changes, their
697	/// state kept; a frequency at or above 0.49·fs is not designed and x passes
698	/// untouched.
699	///
700	/// RBJ in Double, transposed direct form II, scalar per sample over raw
701	/// pointers (never `vDSP_biquad`, S1); the sum by element-wise vDSP. Real-time
702	/// rules (`AudioDSP.swift`'s head): buffers allocated in `init`, chunks at
703	/// capacity; nil settings reset the stage and touch no sample.
704	final class AudioDeEsserStage {
705	    static let attackSeconds = 0.001
706	    static let releaseSeconds = 0.060
707	
708	    /// Sidechain high-pass 1 and 2, the crossover's low-pass and its
709	    /// high-pass (each run twice).
710	    private static let sections = 6
711	    let channelCount: Int
712	    private let sampleRate: Double
713	    private let capacity: Int
714	    /// The four designs: sidechain 1, sidechain 2, crossover low, crossover
715	    /// high.
716	    private let coefficients: UnsafeMutablePointer<AudioBiquadCoefficients>
717	    /// z1, z2 per channel per section: `[(channel · sections + s) · 2]`.
718	    private let state: UnsafeMutablePointer<Double>
719	    private let stateCount: Int
720	    /// `low` and `band` for every channel, `channel · capacity` apart.
721	    private let low: UnsafeMutablePointer<Float>
722	    private let band: UnsafeMutablePointer<Float>
723	    private let sidechain: UnsafeMutablePointer<Float>
724	    private let detector: UnsafeMutablePointer<Float>
725	    private let gains: UnsafeMutablePointer<Float>
726	    private var designedFrequency: Double?
727	    private var reductionDB: Float = 0
728	    private var follower = AudioPeakFollower()
729	
730	    init(channelCount: Int, sampleRate: Double, maxFrames: Int) {
731	        self.channelCount = max(0, channelCount)
732	        self.sampleRate = sampleRate > 0 ? sampleRate : 48_000
733	        capacity = max(1, maxFrames)
734	        coefficients = .allocate(capacity: 4)
735	        coefficients.initialize(repeating: .identity, count: 4)
736	        stateCount = max(1, self.channelCount * Self.sections * 2)
737	        state = .allocate(capacity: stateCount)
738	        state.initialize(repeating: 0, count: stateCount)
739	        let planes = max(1, self.channelCount) * capacity
740	        low = .allocate(capacity: planes)
741	        low.initialize(repeating: 0, count: planes)
742	        band = .allocate(capacity: planes)
743	        band.initialize(repeating: 0, count: planes)
744	        sidechain = .allocate(capacity: capacity)
745	        sidechain.initialize(repeating: 0, count: capacity)
746	        detector = .allocate(capacity: capacity)
747	        detector.initialize(repeating: 0, count: capacity)
748	        gains = .allocate(capacity: capacity)
749	        gains.initialize(repeating: 1, count: capacity)
750	    }
751	
752	    @available(*, unavailable) required init?(coder: NSCoder) {
753	        fatalError("AudioDeEsserStage does not support NSCoder")
754	    }
755	
756	    deinit {
757	        coefficients.deallocate()
758	        state.deallocate()
759	        low.deallocate()
760	        band.deallocate()
761	        sidechain.deallocate()
762	        detector.deallocate()
763	        gains.deallocate()
764	    }
765	
766	    /// A fresh stage: every section's state zero, no reduction, no design.
767	    func reset() {
768	        state.update(repeating: 0, count: stateCount)
769	        reductionDB = 0
770	        follower.reset()
771	        designedFrequency = nil
772	    }
773	
774	    func process(
775	        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
776	        frames: Int, settings: AudioDeEsserSettings?
777	    ) {
778	        guard let settings, settings.frequency < 0.49 * sampleRate else {
779	            reset()
780	            return
781	        }
782	        let used = min(count, channels.count, channelCount)
783	        guard frames > 0, used > 0 else { return }
784	        if designedFrequency != settings.frequency {
785	            design(settings.frequency)
786	        }
787	        var offset = 0
788	        while offset < frames {
789	            let chunk = min(capacity, frames - offset)
790	            processChunk(channels, count: used, offset: offset, frames: chunk, settings: settings)
791	            offset += chunk
792	        }
793	    }
794	
795	    /// The four designs at `frequency`, into storage allocated in `init`.
796	    private func design(_ frequency: Double) {
797	        coefficients[0] = AudioEQDesign.highPass(
798	            frequency, q: AudioEQDesign.butterworthQ(sections: 2, index: 0),
799	            sampleRate: sampleRate)
800	        coefficients[1] = AudioEQDesign.highPass(
801	            frequency, q: AudioEQDesign.butterworthQ(sections: 2, index: 1),
802	            sampleRate: sampleRate)
803	        let q = 0.5.squareRoot()
804	        coefficients[2] = AudioEQDesign.lowPass(frequency, q: q, sampleRate: sampleRate)
805	        coefficients[3] = AudioEQDesign.highPass(frequency, q: q, sampleRate: sampleRate)
806	        designedFrequency = frequency
807	    }
808	
809	    /// One section over `frames` samples of `data`, in place.
810	    @inline(__always)
811	    private func run(
812	        _ c: AudioBiquadCoefficients, _ data: UnsafeMutablePointer<Float>, frames: Int,
813	        state at: Int
814	    ) {
815	        var z1 = state[at]
816	        var z2 = state[at + 1]
817	        for i in 0..<frames {
818	            let x = Double(data[i])
819	            let y = c.b0 * x + z1
820	            z1 = c.b1 * x - c.a1 * y + z2
821	            z2 = c.b2 * x - c.a2 * y
822	            data[i] = Float(y)
823	        }
824	        state[at] = z1
825	        state[at + 1] = z2
826	    }
827	
828	    private func processChunk(
829	        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
830	        offset: Int, frames: Int, settings: AudioDeEsserSettings
831	    ) {
832	        let length = vDSP_Length(frames)
833	        var detected = false
834	        for channel in 0..<count {
835	            guard let data = channels[channel] else { continue }
836	            let input = data + offset
837	            let base = channel * Self.sections * 2
838	            // The sidechain, then |sidechain| into the linked detector.
839	            sidechain.update(from: input, count: frames)
840	            run(coefficients[0], sidechain, frames: frames, state: base)
841	            run(coefficients[1], sidechain, frames: frames, state: base + 2)
842	            vDSP_vabs(sidechain, 1, sidechain, 1, length)
843	            if detected {
844	                vDSP_vmax(detector, 1, sidechain, 1, detector, 1, length)
845	            } else {
846	                detector.update(from: sidechain, count: frames)
847	                detected = true
848	            }
849	            // The crossover's two halves.
850	            let lowPlane = low + channel * capacity
851	            let bandPlane = band + channel * capacity
852	            lowPlane.update(from: input, count: frames)
853	            run(coefficients[2], lowPlane, frames: frames, state: base + 4)
854	            run(coefficients[2], lowPlane, frames: frames, state: base + 6)
855	            bandPlane.update(from: input, count: frames)
856	            run(coefficients[3], bandPlane, frames: frames, state: base + 8)
857	            run(coefficients[3], bandPlane, frames: frames, state: base + 10)
858	        }
859	        guard detected else { return }
860	
861	        let thresholdDB = Float(settings.thresholdDB)
862	        let thresholdLinear = AudioDSP.gain(fromDecibels: thresholdDB)
863	        let range = Float(settings.rangeDB)
864	        let attack = AudioEnvelope.coefficient(seconds: Self.attackSeconds, sampleRate: sampleRate)
865	        let release = AudioEnvelope.coefficient(
866	            seconds: Self.releaseSeconds, sampleRate: sampleRate)
867	        let fall = AudioEnvelope.fall(seconds: 0, sampleRate: sampleRate)
868	        for index in 0..<frames {
869	            let level = follower.follow(detector[index], fall: fall)
870	            var target: Float = 0
871	            if level > thresholdLinear {
872	                target = min(range, 20 * log10f(level) - thresholdDB)
873	            }
874	            let coefficient = target > reductionDB ? attack : release
875	            reductionDB += (target - reductionDB) * coefficient
876	            gains[index] = AudioDSP.gain(fromDecibels: -reductionDB)
877	        }
878	
879	        for channel in 0..<count {
880	            guard let data = channels[channel] else { continue }
881	            let bandPlane = band + channel * capacity
882	            vDSP_vmul(bandPlane, 1, gains, 1, bandPlane, 1, length)
883	            vDSP_vadd(low + channel * capacity, 1, bandPlane, 1, data + offset, 1, length)
884	        }
885	    }
886	}
